using System.Text.Json;using CustomCodeFramework.Messaging.Outbox;using Dhole.Content.Application.Abstractions.Messaging;using Dhole.Content.Persistence.Auditing;using Dhole.Content.Persistence.DbContexts;namespace Dhole.Content.Persistence.Messaging;
public sealed class IntegrationEventOutboxWriter(ServiceDbContext dbContext):IIntegrationEventOutboxWriter
{private const string SourceService="DholeContentService";private static readonly JsonSerializerOptions JsonOptions=new(JsonSerializerDefaults.Web);public Task WriteAsync(string eventName,string eventType,object payload,string? correlationId=null,CancellationToken cancellationToken=default){var resolved=correlationId??AuditExecutionContextAccessor.Current?.CorrelationId.ToString()??Guid.NewGuid().ToString();dbContext.OutboxMessages.Add(new OutboxMessage{EventId=Guid.NewGuid(),EventType=eventType,EventName=eventName,SourceService=SourceService,PayloadJson=JsonSerializer.Serialize(payload,JsonOptions),HeadersJson=null,CorrelationId=resolved,Status=OutboxMessageStatus.Pending,RetryCount=0,ErrorMessage=null,CreatedAtUtc=DateTime.UtcNow});return Task.CompletedTask;}}
